//! Captured-field edits of an existing saved chat; never opens an agent.
use super::*;
const FIELDS:[&str;6]=["title","cwd","instruction","destination","sessionId","itemIds"];
pub fn schema(kind:&str)->Value{
    let id=json!({"type":"string","pattern":"^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$","maxLength":36});
    let mut fields=json!({"title":{"type":"string","maxLength":180},"cwd":{"type":"string","maxLength":4096},"instruction":{"type":"string","maxLength":8000},"destination":{"type":"string","enum":["embedded","desktop"]},"sessionId":{"type":"string","maxLength":36},"itemIds":{"type":"array","maxItems":100,"items":{"type":"string","maxLength":300}}});
    let mut tokens=json!({});for field in FIELDS{tokens[field]=json!({"type":"string","pattern":"^[0-9a-fA-F]{64}$","maxLength":64});}
    if kind=="read"{return json!({"type":"object","properties":{"recordId":id},"required":["recordId"],"additionalProperties":false});}
    fields=json!({"type":"object","properties":fields,"additionalProperties":false});
    json!({"type":"object","properties":{"recordId":id,"patch":fields,"expected":{"type":"object","properties":tokens,"additionalProperties":false},"urls":{"type":"array","maxItems":10,"items":{"type":"string","maxLength":4096}}},"required":["recordId","patch","expected"],"additionalProperties":false})
}
fn conflict(message:&str)->Error{let mut error=Error::new(message);error.status=409;error}
fn exact(repo:&Repository,value:&str)->Result<()>{let mut projected=value.to_owned();commands::redact_text(repo,&mut projected);if projected!=value||value.chars().any(char::is_control){return Err(Error::new("Saved chat identity or edit tokens cannot be safely projected."));}Ok(())}
fn position(state:&Value,id:&str)->Result<usize>{state["sessions"].as_array().and_then(|rows|rows.iter().position(|row|row["id"]==id)).ok_or(Error::new("Saved chat no longer exists."))}
fn ids(row:&Value)->Result<Vec<String>>{
    let items=row["items"].as_array().ok_or(Error::new("Invalid saved chat work links."))?;
    let mut ids=Vec::new();for item in items{let id=item["id"].as_str().filter(|id|!id.is_empty()&&id.chars().count()<=300&&!id.chars().any(char::is_control)).ok_or(Error::new("Invalid saved chat work identity."))?;ids.push(id.to_owned());}ids.sort();ids.dedup();if ids.len()>100{return Err(Error::new("Saved chat exceeds 100 work links."));}Ok(ids)
}
fn token(row:&Value,field:&str)->Result<String>{let value=if field=="itemIds"{json!(ids(row)?)}else if field=="sessionId"{json!({"agent":row["agent"],"sessionId":row["sessionId"]})}else{row[field].clone()};Ok(context_kit::sha256(&serde_json::to_vec(&json!({"recordId":row["id"],"field":field,"value":value}))?))}
fn tokens(repo:&Repository,row:&Value)->Result<Value>{let mut expected=json!({});for field in FIELDS{let hash=token(row,field)?;exact(repo,&hash)?;expected[field]=json!(hash);}Ok(expected)}
fn identity(repo:&Repository,row:&Value)->Result<()>{let id=text(row,"id");if sid(id)?!=id{return Err(Error::new("Invalid saved chat identity."));}if !text(row,"sessionId").is_empty()&&sid(text(row,"sessionId"))?!=text(row,"sessionId"){return Err(Error::new("Invalid conversation identity."));}for value in [id,text(row,"agent"),text(row,"sessionId")]{exact(repo,value)?;}for id in ids(row)?{exact(repo,&id)?;}if !["claude","codex"].contains(&text(row,"agent")){return Err(Error::new("Invalid saved assistant identity."));}Ok(())}
fn view(repo:&Repository,row:&Value)->Result<Value>{
    identity(repo,row)?;if !["embedded","desktop","cmux"].contains(&text(row,"destination"))||(row["agent"]=="claude"&&row["destination"]=="desktop"){return Err(Error::new("Invalid saved launch destination."));}let mut chat=json!({"agent":row["agent"],"itemIds":ids(row)?});let mut redacted=false;
    for (field,bound) in [("title",180),("cwd",4096),("instruction",8000),("destination",32),("sessionId",36)]{let value=match row.get(field){Some(Value::String(value))=>value.as_str(),None|Some(Value::Null) if ["instruction","sessionId"].contains(&field)=>"",_=>return Err(Error::new("Invalid saved chat field type."))};if value.chars().count()>bound||value.contains('\0'){return Err(Error::new("Saved chat exceeds its editable field limit."));}let mut display=value.to_owned();commands::redact_text(repo,&mut display);if display!=value{redacted=true;}if ["destination","sessionId"].contains(&field){exact(repo,value)?;}chat[field]=json!(display);}
    Ok(json!({"recordId":row["id"],"chat":chat,"expected":tokens(repo,row)?,"redacted":redacted}))
}
pub fn read(repo:&Repository,args:&Value)->Result<Value>{commands::validate_chat_metadata_arguments("read",args)?;let state=repo.state.lock().map_err(|_|Error::io())?;view(repo,&state["sessions"][position(&state,text(args,"recordId"))?])}
fn validate(repo:&Repository,args:&Value)->Result<Value>{
    commands::validate_chat_metadata_arguments("update",args)?;if serde_json::to_vec(args)?.len()>65536{return Err(Error::new("Chat edit exceeds 64 KiB."));}
    let patch=args["patch"].as_object().unwrap();let expected=args["expected"].as_object().unwrap();if patch.is_empty()||patch.len()!=expected.len()||patch.keys().any(|field|!expected.contains_key(field)){return Err(Error::new("Supply captured tokens for exactly the changed chat fields."));}
    for field in FIELDS{exact(repo,field)?;}exact(repo,text(args,"recordId"))?;for value in expected.values(){exact(repo,value.as_str().unwrap())?;}
    if !arr(&args["urls"]).is_empty()&&!patch.contains_key("itemIds"){return Err(Error::new("Importing links requires the captured complete work-link field."));}
    for url in arr(&args["urls"]){if safe_url(url.as_str().unwrap())?.is_empty(){return Err(Error::new("Supply nonempty work URLs."));}}
    let mut normalized=args["patch"].clone();
    for field in ["title","instruction","cwd"]{if patch.contains_key(field){let value=checked(&args["patch"],field,if field=="title"{180}else if field=="instruction"{8000}else{4096},field!="instruction")?;if field=="title"&&value.chars().any(char::is_control){return Err(Error::new("Chat titles cannot contain control characters."));}normalized[field]=json!(if field=="cwd"{directory(&value)?}else{value});}}
    if patch.contains_key("sessionId"){let value=text(&args["patch"],"sessionId");normalized["sessionId"]=json!(if value.is_empty(){String::new()}else{sid(value)?});exact(repo,text(&normalized,"sessionId"))?;}
    if let Some(values)=patch.get("itemIds"){let mut collected=vec![];for value in values.as_array().unwrap(){let id=value.as_str().unwrap();if id.is_empty()||id.chars().any(char::is_control){return Err(Error::new("Invalid work identity."));}exact(repo,id)?;collected.push(id.to_owned());}collected.sort();collected.dedup();normalized["itemIds"]=json!(collected);}
    Ok(normalized)
}
fn check_tokens(row:&Value,args:&Value)->Result<()>{for field in args["patch"].as_object().unwrap().keys(){if args["expected"][field]!=token(row,field)?{return Err(conflict("A changed chat field was edited elsewhere. Read it again and reapply only your intended changes."));}}Ok(())}
fn association(state:&Value,current:&Value,patch:&Value,repo:&Repository)->Result<()>{
    if let Some(value)=patch.get("sessionId"){let old=text(&current,"sessionId");if !old.is_empty()&&value.as_str()!=Some(old){return Err(conflict("An attached conversation identity cannot be changed."));}if !text(patch,"sessionId").is_empty()&&arr(&state["sessions"]).iter().any(|row|row["id"]!=current["id"]&&row["agent"]==current["agent"]&&row["sessionId"]==*value){return Err(conflict("This conversation is already associated with another saved chat."));}}
    let destination=patch.get("destination").unwrap_or(&current["destination"]);exact(repo,destination.as_str().unwrap_or(""))?;if current["agent"]=="claude"&&destination=="desktop"{return Err(Error::new("Claude chats require the embedded terminal."));}
    Ok(())
}
fn apply(repo:&Repository,state:&mut Value,args:&Value,patch:&Value,imported:&[Value])->Result<Value>{
    let index=position(state,text(args,"recordId"))?;let current=state["sessions"][index].clone();identity(repo,&current)?;check_tokens(&current,args)?;
    association(state,&current,patch,repo)?;
    let mut next=current.clone();let mut changed=vec![];
    if let Some(requested)=patch.get("itemIds"){
        let mut requested=arr(requested);for item in imported{requested.push(item["id"].clone());}requested.sort_by_key(Value::to_string);requested.dedup();if requested.len()>100{return Err(Error::new("Choose up to 100 linked work items."));}
        let mut catalog=domain::catalog(state);for item in imported{catalog.entry(text(item,"id").to_owned()).or_insert_with(||item.clone());}
        let mut linked=vec![];for value in &requested{let id=value.as_str().ok_or(Error::new("Invalid imported work identity."))?;exact(repo,id)?;let item=catalog.get(id).ok_or(Error::new("A linked work item no longer exists."))?;linked.push(arr(&current["items"]).into_iter().find(|old|old["id"]==*value).unwrap_or_else(||domain::item_ref(item)));}
        if json!(ids(&current)?)!=json!(requested){next["items"]=json!(linked);changed.push("itemIds".to_owned());}
        // Provider reads cannot replace newer cached source data merely to associate it.
        for item in imported{if !domain::catalog(state).contains_key(text(item,"id")){state["items"].as_array_mut().ok_or(Error::io())?.push(item.clone());}}
    }
    for (field,value) in patch.as_object().unwrap(){if field=="itemIds"{continue;}let old=if field=="sessionId"{json!(text(&current,"sessionId"))}else{current[field].clone()};if old!=*value{next[field]=value.clone();changed.push(field.clone());if field=="sessionId"&&!text(&next,"sessionId").is_empty(){next["launchNew"]=json!(false);}}}
    if !changed.is_empty(){next["updatedAt"]=json!(now());}identity(repo,&next)?;let expected=tokens(repo,&next)?;state["sessions"][index]=next;
    Ok(json!({"recordId":current["id"],"saved":true,"changedFields":changed,"expected":expected}))
}
pub fn update(repo:&Repository,args:&Value)->Result<Value>{update_with(repo,args,|url|repo.providers.resolve(url))}
fn update_with(repo:&Repository,args:&Value,resolve:impl Fn(&str)->Result<Value>)->Result<Value>{
    let patch=validate(repo,args)?;
    {let state=repo.state.lock().map_err(|_|Error::io())?;let row=&state["sessions"][position(&state,text(args,"recordId"))?];identity(repo,row)?;check_tokens(row,args)?;association(&state,row,&patch,repo)?;}
    let mut imported=vec![];for url in arr(&args["urls"]){let url=safe_url(url.as_str().unwrap())?;let cached={let state=repo.state.lock().map_err(|_|Error::io())?;domain::catalog(&state).into_values().find(|row|row["url"]==url)};imported.push(match cached{Some(row)=>row,None=>resolve(&url)?});}
    repo.transaction_if_changed(|state|apply(repo,state,args,&patch,&imported))
}
pub(super) fn reject_unchecked_association(state:&Value,args:&Value)->Result<()>{
    if args.get("id").is_some_and(|value|!value.is_string()){return Err(Error::new("Invalid saved chat ID."));}
    if !text(args,"sessionId").is_empty()&&arr(&state["sessions"]).iter().any(|row|row["agent"]==args["agent"]&&row["sessionId"]==args["sessionId"]){return Err(conflict("This conversation is already saved. Reopen Manage to capture current chat fields."));}Ok(())
}
/// Old edit transports require the same captured patch; registration is a separate owner.
pub(super) fn legacy(repo:&Repository,args:&Value)->Result<Value>{
    let object=args.as_object().ok_or(Error::new("Invalid chat edit."))?;if object.keys().any(|key|!["action","id","patch","expected","urls"].contains(&key.as_str())){return Err(conflict("Reopen Manage to capture current chat fields before editing."));}
    let request=json!({"recordId":args["id"],"patch":args["patch"],"expected":args["expected"],"urls":args.get("urls").cloned().unwrap_or(json!([]))});update(repo,&request)?;
    let state=repo.state.lock().map_err(|_|Error::io())?;Ok(state["sessions"][position(&state,text(args,"id"))?].clone())
}

#[cfg(test)]
mod tests{
 use super::*;
 use std::sync::Arc;
 fn fixture()->(tempfile::TempDir,Arc<Repository>,String){let temp=tempfile::tempdir().unwrap();let repo=Repository::open(temp.path().into(),None,true).unwrap();let id=uuid();repo.transaction(|s|{s["sessions"]=json!([{ "id":id,"agent":"codex","sessionId":null,"launchNew":true,"title":"Initial","cwd":temp.path(),"instruction":"Initial instruction","destination":"embedded","items":[{"id":"note:a","source":"notes","title":"A","linkExtension":{"retain":true}}],"futureNs":{"private":"retain"},"preparationRequests":{"version":1,"entries":[]},"runtime":{"state":"running"},"resources":[{"future":1}]}]);s["notes"]=json!([{ "id":"note:a","source":"notes","title":"A"},{"id":"note:b","source":"notes","title":"B"}]);s["itemSettings"]["note:a"]=json!({"cwd":"independent folder","explicit":true});Ok(())}).unwrap();(temp,repo,id)}
 fn baseline(repo:&Repository,id:&str)->Value{read(repo,&json!({"recordId":id})).unwrap()}
 fn request(base:&Value,patch:Value)->Value{let mut expected=json!({});for key in patch.as_object().unwrap().keys(){expected[key]=base["expected"][key].clone();}json!({"recordId":base["recordId"],"patch":patch,"expected":expected})}
 #[test]
 fn chat_metadata_patched_fields_commute_and_preserve_latest_extensions_folders_and_aliases(){let (_temp,repo,id)=fixture();let old=baseline(&repo,&id);update(&repo,&request(&old,json!({"itemIds":["note:a","note:b"]}))).unwrap();update(&repo,&request(&old,json!({"title":"Renamed"}))).unwrap();let current=baseline(&repo,&id);assert_eq!(current["chat"]["itemIds"],json!(["note:a","note:b"]));assert_eq!(current["chat"]["title"],"Renamed");let state=repo.state.lock().unwrap().clone();let row=&state["sessions"][0];assert_eq!(row["futureNs"]["private"],"retain");assert_eq!(row["preparationRequests"],json!({"version":1,"entries":[]}));assert_eq!(row["runtime"]["state"],"running");assert_eq!(row["items"][0]["linkExtension"]["retain"],true);assert_eq!(row["resources"],json!([{"future":1}]));assert_eq!(state["itemSettings"]["note:a"]["cwd"],"independent folder");assert!(state["itemSettings"].get("note:b").is_none());assert!(!current.to_string().contains("retain"));}
 #[test]
 fn chat_metadata_stale_mixed_patch_and_bad_shape_leave_state_and_disk_unchanged(){let (_temp,repo,id)=fixture();let old=baseline(&repo,&id);update(&repo,&request(&old,json!({"title":"Concurrent"}))).unwrap();let before=repo.state.lock().unwrap().clone();let bytes=std::fs::read(&repo.data).unwrap();assert_eq!(update(&repo,&request(&old,json!({"title":"Stale","instruction":"Do not apply"}))).unwrap_err().status,409);let valid=baseline(&repo,&id);for bad in [json!({"recordId":id,"patch":{},"expected":{}}),json!({"recordId":id,"patch":{"title":"Bad"},"expected":{}}),json!({"recordId":id,"patch":{"agent":"claude"},"expected":{"agent":"0".repeat(64)}}),json!({"recordId":id,"patch":{"title":"Bad"},"expected":{"title":valid["expected"]["title"],"cwd":valid["expected"]["cwd"]}})]{assert!(update(&repo,&bad).is_err());}assert_eq!(*repo.state.lock().unwrap(),before);assert_eq!(std::fs::read(&repo.data).unwrap(),bytes);}
 #[test]
 fn chat_metadata_link_tokens_ignore_ref_refresh_but_conflict_on_relationship_change(){let (_temp,repo,id)=fixture();let old=baseline(&repo,&id);repo.transaction(|s|{s["sessions"][0]["items"][0]["title"]=json!("Refreshed source title");Ok(())}).unwrap();assert_eq!(baseline(&repo,&id)["expected"]["itemIds"],old["expected"]["itemIds"]);update(&repo,&request(&old,json!({"itemIds":["note:b"]}))).unwrap();assert_eq!(update(&repo,&request(&old,json!({"itemIds":["note:a"]}))).unwrap_err().status,409);}
 #[test]
 fn chat_metadata_association_only_fills_empty_identity_and_detects_conflicts(){let (_temp,repo,id)=fixture();let old=baseline(&repo,&id);let session=uuid();update(&repo,&request(&old,json!({"sessionId":session}))).unwrap();assert_eq!(repo.state.lock().unwrap()["sessions"][0]["launchNew"],false);assert_eq!(update(&repo,&request(&old,json!({"sessionId":uuid()}))).unwrap_err().status,409);let latest=baseline(&repo,&id);assert_eq!(update(&repo,&request(&latest,json!({"sessionId":""}))).unwrap_err().status,409);let (_other,repo,id)=fixture();let old=baseline(&repo,&id);repo.transaction(|s|{let mut other=s["sessions"][0].clone();other["id"]=json!(uuid());other["sessionId"]=json!(session);s["sessions"].as_array_mut().unwrap().push(other);Ok(())}).unwrap();assert_eq!(update(&repo,&request(&old,json!({"sessionId":session}))).unwrap_err().status,409);}
 #[test]
 fn chat_metadata_url_resolution_rechecks_tokens_and_never_overwrites_newer_cache(){let (_temp,repo,id)=fixture();let old=baseline(&repo,&id);let mut args=request(&old,json!({"itemIds":["note:a"]}));args["urls"]=json!(["https://example.invalid/work"]);let mut empty=args.clone();empty["urls"]=json!([""]);assert!(update_with(&repo,&empty,|_|panic!("Empty URLs must fail before provider resolution")).is_err());let bytes=std::fs::read(&repo.data).unwrap();let result=update_with(&repo,&args,|_|{repo.transaction(|s|{s["sessions"][0]["items"].as_array_mut().unwrap().push(json!({"id":"note:b","source":"notes","title":"B"}));Ok(())})?;Ok(json!({"id":"github:new","source":"github","title":"New","url":"https://example.invalid/work"}))});assert_eq!(result.unwrap_err().status,409);assert!(domain::catalog(&repo.state.lock().unwrap()).get("github:new").is_none());assert_ne!(std::fs::read(&repo.data).unwrap(),bytes);
 let latest=baseline(&repo,&id);let mut args=request(&latest,json!({"itemIds":["note:a","note:b"]}));args["urls"]=json!(["https://example.invalid/work"]);update_with(&repo,&args,|_|{repo.transaction(|s|{s["items"].as_array_mut().unwrap().push(json!({"id":"github:new","source":"github","title":"Newer","url":"https://example.invalid/work"}));Ok(())})?;Ok(json!({"id":"github:new","source":"github","title":"Old result","url":"https://example.invalid/work"}))}).unwrap();assert_eq!(domain::catalog(&repo.state.lock().unwrap())["github:new"]["title"],"Newer");assert_eq!(baseline(&repo,&id)["chat"]["itemIds"].as_array().unwrap().len(),3);}
 #[test]
 fn chat_metadata_failed_persistence_rolls_back_and_retry_succeeds(){let (_temp,repo,id)=fixture();let old=baseline(&repo,&id);let before=repo.state.lock().unwrap().clone();let bytes=std::fs::read(&repo.data).unwrap();let blocker=repo.data.with_extension("tmp");std::fs::create_dir(&blocker).unwrap();assert!(update(&repo,&request(&old,json!({"title":"After failure"}))).is_err());assert_eq!(*repo.state.lock().unwrap(),before);assert_eq!(std::fs::read(&repo.data).unwrap(),bytes);std::fs::remove_dir(blocker).unwrap();update(&repo,&request(&old,json!({"title":"After failure"}))).unwrap();}
 #[test]
 fn chat_metadata_legacy_requires_checked_patch_and_does_not_resolve_unchecked_urls(){let (_temp,repo,id)=fixture();let old=baseline(&repo,&id);let before=std::fs::read(&repo.data).unwrap();assert_eq!(workflows::prepare(&repo,&json!({"id":id,"agent":"codex","title":"Unchecked","urls":["not a URL"]})).unwrap_err().status,409);assert!(repo.edit(&json!({"action":"save-session","id":id,"title":"Unchecked"})).is_err());assert_eq!(std::fs::read(&repo.data).unwrap(),before);assert!(workflows::prepare(&repo,&json!({"id":3,"agent":"codex","title":"Invalid ID"})).is_err());let checked=request(&old,json!({"title":"Checked legacy"}));workflows::prepare(&repo,&json!({"id":id,"patch":checked["patch"],"expected":checked["expected"]})).unwrap();assert_eq!(baseline(&repo,&id)["chat"]["title"],"Checked legacy");}
 #[test]
 fn chat_metadata_command_redaction_preserves_tokens_and_hides_reference_text(){let temp=tempfile::tempdir().unwrap();let secret="private-chat-metadata-canary";std::fs::write(temp.path().join(".env"),format!("METADATA_TEST_SECRET={secret}\n")).unwrap();let repo=Repository::open(temp.path().into(),None,true).unwrap();let id=uuid();repo.transaction(|s|{s["sessions"]=json!([{"id":id,"agent":"codex","title":"Title","cwd":temp.path(),"instruction":format!("Use {secret} as reference"),"destination":"embedded","sessionId":null,"items":[]}]);Ok(())}).unwrap();let base=commands::invoke(&repo,&json!({"name":"chats.metadata.read","args":{"recordId":id}}),true).unwrap();assert_eq!(base["redacted"],true);assert!(!base.to_string().contains(secret));let result=commands::invoke(&repo,&json!({"name":"chats.metadata.update","args":request(&base,json!({"title":"Changed"}))}),false).unwrap();assert_eq!(result["recordId"],id);assert_eq!(repo.state.lock().unwrap()["sessions"][0]["instruction"],format!("Use {secret} as reference"));repo.transaction(|s|{s["sessions"][0]["items"]=json!([{"id":secret}]);Ok(())}).unwrap();assert!(read(&repo,&json!({"recordId":id})).is_err());let bytes=std::fs::read(&repo.data).unwrap();assert!(update(&repo,&request(&base,json!({"itemIds":[secret]}))).is_err());assert_eq!(std::fs::read(&repo.data).unwrap(),bytes);}
 #[test]
 fn chat_metadata_concurrent_same_field_allows_one_commit(){let (_temp,repo,id)=fixture();let old=baseline(&repo,&id);let barrier=Arc::new(std::sync::Barrier::new(3));let threads=(0..2).map(|n|{let repo=repo.clone();let barrier=barrier.clone();let args=request(&old,json!({"title":format!("Writer {n}")}));std::thread::spawn(move||{barrier.wait();update(&repo,&args)})}).collect::<Vec<_>>();barrier.wait();let results=threads.into_iter().map(|t|t.join().unwrap()).collect::<Vec<_>>();assert_eq!(results.iter().filter(|r|r.is_ok()).count(),1);assert_eq!(results.iter().filter(|r|r.as_ref().err().is_some_and(|e|e.status==409)).count(),1);}
 #[test]
 fn chat_metadata_invalid_stored_fields_fail_closed_and_legacy_association_cannot_bypass(){let (_temp,repo,id)=fixture();let session=uuid();repo.transaction(|s|{s["sessions"][0]["sessionId"]=json!(session);Ok(())}).unwrap();let bytes=std::fs::read(&repo.data).unwrap();let payload=json!({"agent":"codex","sessionId":session,"title":"Unchecked","cwd":"invalid","urls":["invalid"]});assert_eq!(workflows::prepare(&repo,&payload).unwrap_err().status,409);let mut edit=payload.clone();edit["action"]=json!("save-session");assert_eq!(repo.edit(&edit).unwrap_err().status,409);assert_eq!(std::fs::read(&repo.data).unwrap(),bytes);
 for (field,value) in [("title",json!(42)),("cwd",json!(null)),("instruction",json!({"bad":true})),("destination",json!(false)),("destination",json!("unexpected")),("sessionId",json!("not-a-uuid"))]{repo.transaction(|s|{s["sessions"][0][field]=value.clone();Ok(())}).unwrap();assert!(read(&repo,&json!({"recordId":id})).is_err());repo.transaction(|s|{s["sessions"][0][field]=json!(match field{"title"=>"Initial","cwd"=>"/unvalidated/read-only/saved/path","instruction"=>"Reference","destination"=>"embedded",_=>session.as_str()});Ok(())}).unwrap();}
 }
 #[test]
 fn chat_metadata_read_is_pure_and_preserves_complete_link_set(){let (_temp,repo,id)=fixture();repo.transaction(|s|{s["sessions"][0]["items"]=json!((0..100).map(|i|json!({"id":format!("archived:{i}"),"title":"Cached"})).collect::<Vec<_>>());Ok(())}).unwrap();let state=repo.state.lock().unwrap().clone();let bytes=std::fs::read(&repo.data).unwrap();let result=baseline(&repo,&id);assert_eq!(result["chat"]["itemIds"].as_array().unwrap().len(),100);assert_eq!(*repo.state.lock().unwrap(),state);assert_eq!(std::fs::read(&repo.data).unwrap(),bytes);update(&repo,&request(&result,json!({"title":"Only title"}))).unwrap();assert_eq!(baseline(&repo,&id)["chat"]["itemIds"],result["chat"]["itemIds"]);}
}
